package engine

import (
	"context"
	"fmt"
	"strings"
	"time"
)

// tryExecConditionalDDL intercepts conditional DDL statements commonly generated by migration tools (e.g. XORM, GORM, EF Core)
// such as:
//   - IF NOT EXISTS (SELECT ...) CREATE TABLE ...
//   - IF EXISTS (SELECT ...) DROP TABLE ...
//   - IF OBJECT_ID(...) IS NULL CREATE TABLE ...
//   - IF NOT EXISTS (...) BEGIN CREATE TABLE ...; CREATE INDEX ...; END
func (s *Coordinator) tryExecConditionalDDL(query string, start time.Time, cs *ClientSession) (*QueryResult, bool, error) {
	trimmed := strings.TrimSpace(query)
	upper := strings.ToUpper(trimmed)
	if !strings.HasPrefix(upper, "IF ") && !strings.HasPrefix(upper, "IF\t") && !strings.HasPrefix(upper, "IF\n") {
		return nil, false, nil
	}

	afterIf := strings.TrimSpace(trimmed[2:])
	upperAfter := strings.ToUpper(afterIf)

	// 1. Pattern: IF [NOT] EXISTS ( <subquery> ) <body...>
	var isNot bool
	openParen := -1

	if strings.HasPrefix(upperAfter, "NOT") {
		rest := strings.TrimSpace(afterIf[3:])
		if strings.HasPrefix(strings.ToUpper(rest), "EXISTS") {
			isNot = true
			idx := strings.Index(rest, "(")
			if idx != -1 {
				openParen = len(afterIf) - len(rest) + idx
			}
		}
	} else if strings.HasPrefix(upperAfter, "EXISTS") {
		isNot = false
		openParen = strings.Index(afterIf, "(")
	}

	if openParen != -1 {
		closeParen := findMatchingParen(afterIf, openParen)
		if closeParen != -1 && closeParen+1 < len(afterIf) {
			subquery := strings.TrimSpace(afterIf[openParen+1 : closeParen])
			body := strings.TrimSpace(afterIf[closeParen+1:])
			if isDDLStatement(body) {
				thenClause, elseClause := splitTopLevelElse(body)

				subRes, err := s.runInternalQuery(cs, subquery)
				if err != nil {
					return nil, true, fmt.Errorf("conditional DDL subquery error: %w", err)
				}
				hasRows := subRes != nil && len(subRes.Rows) > 0
				condMet := hasRows
				if isNot {
					condMet = !hasRows
				}

				if condMet {
					inner := unwrapBlock(thenClause)
					res, err := s.runInternalQuery(cs, inner)
					return res, true, err
				} else if elseClause != "" {
					inner := unwrapBlock(elseClause)
					res, err := s.runInternalQuery(cs, inner)
					return res, true, err
				}

				return &QueryResult{
					Success:    true,
					Command:    "IF",
					DurationUS: time.Since(start).Microseconds(),
				}, true, nil
			}
		}
	}

	// 2. Pattern: IF OBJECT_ID(...) IS [NOT] NULL <body...>
	if strings.HasPrefix(upperAfter, "OBJECT_ID") {
		objOpen := strings.Index(afterIf, "(")
		if objOpen != -1 {
			objClose := findMatchingParen(afterIf, objOpen)
			if objClose != -1 && objClose+1 < len(afterIf) {
				objCall := strings.TrimSpace(afterIf[:objClose+1])
				rest := strings.TrimSpace(afterIf[objClose+1:])
				upperRest := strings.ToUpper(rest)

				var isNull bool
				var body string
				matched := false

				if strings.HasPrefix(upperRest, "IS NOT NULL") {
					isNull = false
					body = strings.TrimSpace(rest[len("IS NOT NULL"):])
					matched = true
				} else if strings.HasPrefix(upperRest, "IS NULL") {
					isNull = true
					body = strings.TrimSpace(rest[len("IS NULL"):])
					matched = true
				}

				if matched && isDDLStatement(body) {
					thenClause, elseClause := splitTopLevelElse(body)

					objRes, err := s.runInternalQuery(cs, "SELECT "+objCall+" AS id")
					if err != nil {
						return nil, true, fmt.Errorf("conditional DDL OBJECT_ID error: %w", err)
					}

					var idVal int64
					if objRes != nil && len(objRes.Rows) > 0 && objRes.Rows[0]["id"] != nil {
						switch v := objRes.Rows[0]["id"].(type) {
						case int64:
							idVal = v
						case int:
							idVal = int64(v)
						case int32:
							idVal = int64(v)
						}
					}
					exists := idVal > 0
					condMet := exists
					if isNull {
						condMet = !exists
					}

					if condMet {
						inner := unwrapBlock(thenClause)
						res, err := s.runInternalQuery(cs, inner)
						return res, true, err
					} else if elseClause != "" {
						inner := unwrapBlock(elseClause)
						res, err := s.runInternalQuery(cs, inner)
						return res, true, err
					}

					return &QueryResult{
						Success:    true,
						Command:    "IF",
						DurationUS: time.Since(start).Microseconds(),
					}, true, nil
				}
			}
		}
	}

	return nil, false, nil
}

func (s *Coordinator) runInternalQuery(cs *ClientSession, sql string) (*QueryResult, error) {
	if cs != nil {
		ctx := context.Background()
		cs.Mu.Lock()
		if cs.QueryCtx != nil {
			ctx = cs.QueryCtx
		}
		sessID := cs.ID
		cs.Mu.Unlock()
		return s.ExecuteSessionSQLContext(ctx, sessID, sql)
	}
	return s.ExecuteSQL(sql)
}

// isDDLStatement inspects whether the body (possibly wrapped in BEGIN...END or comments) contains a DDL statement.
func isDDLStatement(stmt string) bool {
	s := strings.TrimSpace(stmt)
	for {
		if strings.HasPrefix(s, "/*") {
			end := strings.Index(s, "*/")
			if end != -1 {
				s = strings.TrimSpace(s[end+2:])
				continue
			}
		}
		if strings.HasPrefix(s, "--") {
			end := strings.Index(s, "\n")
			if end != -1 {
				s = strings.TrimSpace(s[end+1:])
				continue
			}
			return false
		}
		break
	}

	upper := strings.ToUpper(s)
	if strings.HasPrefix(upper, "BEGIN") && (len(upper) == 5 || upper[5] == ' ' || upper[5] == '\t' || upper[5] == '\n') {
		s = strings.TrimSpace(s[5:])
		upper = strings.ToUpper(s)
	}

	return strings.HasPrefix(upper, "CREATE ") ||
		strings.HasPrefix(upper, "DROP ") ||
		strings.HasPrefix(upper, "ALTER ") ||
		strings.HasPrefix(upper, "TRUNCATE ")
}

// unwrapBlock removes enclosing BEGIN ... END blocks and trailing semicolons.
func unwrapBlock(stmt string) string {
	s := strings.TrimSpace(stmt)
	s = strings.TrimRight(s, ";")
	s = strings.TrimSpace(s)

	upper := strings.ToUpper(s)
	if strings.HasPrefix(upper, "BEGIN") && (len(upper) == 5 || upper[5] == ' ' || upper[5] == '\t' || upper[5] == '\n') {
		if strings.HasSuffix(upper, "END") {
			inner := strings.TrimSpace(s[5 : len(s)-3])
			return strings.TrimRight(inner, ";")
		}
	}
	return s
}

// splitTopLevelElse finds the top-level ELSE keyword outside of quotes, parenthesized expressions, and BEGIN...END blocks.
func splitTopLevelElse(body string) (string, string) {
	n := len(body)
	inQuote := false
	quoteChar := byte(0)
	depth := 0
	blockDepth := 0

	for i := 0; i < n; i++ {
		ch := body[i]
		if inQuote {
			if ch == quoteChar && (i == 0 || body[i-1] != '\\') {
				inQuote = false
			}
			continue
		}
		if ch == '\'' || ch == '"' {
			inQuote = true
			quoteChar = ch
			continue
		}
		if ch == '(' {
			depth++
			continue
		} else if ch == ')' {
			if depth > 0 {
				depth--
			}
			continue
		}

		if (i == 0 || !IsIdentChar(body[i-1])) && i+5 <= n && strings.EqualFold(body[i:i+5], "BEGIN") && (i+5 == n || !IsIdentChar(body[i+5])) {
			blockDepth++
			i += 4
			continue
		}
		if (i == 0 || !IsIdentChar(body[i-1])) && i+3 <= n && strings.EqualFold(body[i:i+3], "END") && (i+3 == n || !IsIdentChar(body[i+3])) {
			if blockDepth > 0 {
				blockDepth--
			}
			i += 2
			continue
		}

		if depth == 0 && blockDepth == 0 {
			if (i == 0 || !IsIdentChar(body[i-1])) && i+4 <= n && strings.EqualFold(body[i:i+4], "ELSE") && (i+4 == n || !IsIdentChar(body[i+4])) {
				thenPart := strings.TrimSpace(body[:i])
				elsePart := strings.TrimSpace(body[i+4:])
				return thenPart, elsePart
			}
		}
	}

	return strings.TrimSpace(body), ""
}
